INSERT INTO site_content (key, title, body, updated_at) VALUES ('about', 'About Math & Finance Pro', 'Math & Finance Pro is a professional-grade library of financial formulas, ratios and analytical tools built for analysts, founders, students and finance teams.

We believe numbers tell the story of every business. Our mission is to make that story clear — with precise calculators, transparent formulas and practical resources you can trust when real decisions are on the line.', '2026-10-25T16:35:59.550846+00:00') ON CONFLICT (key) DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, updated_at = EXCLUDED.updated_at;
