INSERT INTO course_sections (id, unit_id, title, content, sort_order) VALUES ('93d3c8f4-258d-45a2-a175-2475876ec649', 'a6b58d3d-0bd9-48e2-be46-0decc5b9f473', 'Environmentalism', 'BLOCKS:[{"id":"x1wfvpnr","t":"desc","text":"Read this section to gain an understanding of the environmental impacts of businesses and the importance of sustainability.\n","photos":[]},{"id":"1qtgpa8f","t":"article","text":"Today, virtually everyone agrees that companies must figure out how to produce products without compromising the right of future generations to meet their own needs. Clearly, protecting natural resources is the right thing to do, but it also has become a business necessity. Companies'' customers demand that they respect the environment. Let''s identify some key environmental issues and highlight the ways in which the business community has addressed them.\n\n","photos":[]}]', 3) ON CONFLICT (id) DO UPDATE SET unit_id = EXCLUDED.unit_id, title = EXCLUDED.title, content = EXCLUDED.content, sort_order = EXCLUDED.sort_order;
INSERT INTO course_sections (id, unit_id, title, content, sort_order) VALUES ('188589d9-485f-49a1-853d-6aa81f700e3a', 'a6b58d3d-0bd9-48e2-be46-0decc5b9f473', 'Corporate Social Responsibility', 'BLOCKS:[{"id":"8tbkukzs","t":"desc","text":"Read this section, paying particular attention to the sections on communities, financial contributions, volunteerism, and supporting local causes to learn more about the positive impact of businesses.\n","photos":[]},{"id":"vt2nt0zy","t":"article","text":"Corporate social responsibility refers to the approach that an organization takes in balancing its responsibilities toward different stakeholders when making legal, economic, ethical, and social decisions. What motivates companies to be \"socially responsible\" to their various stakeholders? We hope it''s because they want to do the right thing, and for many companies, \"doing the right thing\" is a key motivator. The fact is, it''s often hard to figure out what the \"right thing\" is: What''s \"right\" for one group of stakeholders isn''t necessarily just as \"right\" for another. One thing, however, is certain: Companies today are held to higher standards than ever before. Consumers and other groups consider not only the quality and price of a company''s products but also its character. If too many groups see a company as a poor corporate citizen, it will have a harder time attracting qualified employees, finding investors, and selling its products. Good corporate citizens, by contrast, are more successful in all these areas.\n\nFigure 2.6 \"The Corporate Citizen\" presents a model of corporate responsibility based on a company''s relationships with its stakeholders. In this model, the focus is on managers – not owners – as the principals involved in all these relationships. Here, owners are the stakeholders who invest risk capital in the firm in expectation of a financial return. Other stakeholders include employees, suppliers, and the communities in which the firm does business. Proponents of this model hold that customers, who provide the firm with revenue, have a special claim on managers'' attention. The arrows indicate the two-way nature of corporation-stakeholder relationships: All stakeholders have some claim on the firm''s resources and returns, and it''s management''s job to make decisions that balance these claims.","photos":[{"path":"lessons/af5a62b5-128c-4345-a98d-3408545c0e7d-Figure_2.6.jpg","caption":""}]},{"id":"8jfwpt1r","t":"article","text":"Let''s look at some of the ways in which companies can be \"socially responsible\" in considering the claims of various stakeholders.","photos":[]}]', 2) ON CONFLICT (id) DO UPDATE SET unit_id = EXCLUDED.unit_id, title = EXCLUDED.title, content = EXCLUDED.content, sort_order = EXCLUDED.sort_order;
INSERT INTO course_sections (id, unit_id, title, content, sort_order) VALUES ('651d807f-e599-4a45-b71e-dc839654adb0', 'a6b58d3d-0bd9-48e2-be46-0decc5b9f473', 'Getting Down to Business', 'BLOCKS:[{"id":"v7p204cp","t":"desc","text":"Read this section to learn about internal and external factors that affect the success of businesses. Pay particular attention to Figure 1.2 to gain an understanding of where each of these factors falls.\n","photos":[]},{"id":"k8d5fjrl","t":"article","text":"A business is any activity that provides goods or services to consumers for the purpose of making a profit. When Steve Jobs and Steve Wozniak created Apple Computer in Jobs''s family garage, they started a business. The product was the Apple I, and the company''s founders hoped to sell their computers to customers for more than it cost to make and market them. If they were successful (which they were), they''d make a profit.\n\nBefore we go on, let''s make a couple of important distinctions concerning the terms in our definitions. First, whereas Apple produces and sells goods (Mac, iPhone, iPod, iPad), many businesses provide services. Your bank is a service company, as is your Internet provider. Hotels, airlines, law firms, movie theaters, and hospitals are also service companies. Many companies provide both goods and services. For example, your local car dealership sells goods (cars) and also provides services (automobile repairs).\n\nSecond, some organizations are not set up to make profits. Many are established to provide social or educational services. Such not-for-profit (or nonprofit) organizations include the United Way of America, Habitat for Humanity, the Boys and Girls Clubs, the Sierra Club, the American Red Cross, and many colleges and universities. Most of these organizations, however, function in much the same way as a business. They establish goals and work to meet them in an effective, efficient manner. Thus, most of the business principles introduced in this text also apply to nonprofits.\n\n","photos":[]}]', 1) ON CONFLICT (id) DO UPDATE SET unit_id = EXCLUDED.unit_id, title = EXCLUDED.title, content = EXCLUDED.content, sort_order = EXCLUDED.sort_order;
INSERT INTO course_sections (id, unit_id, title, content, sort_order) VALUES ('45446ff3-24db-4928-8efe-90b47259c32c', 'a6b58d3d-0bd9-48e2-be46-0decc5b9f473', 'Case Study', 'BLOCKS:[{"id":"jxcrd3vn","t":"desc","text":"Now that you''ve read about some of the positive and negative impacts of businesses, complete this activity to determine whether Nike was responsible for compensating Honduran factory workers. Consider how Nike impacted society, and determine whether you think their impact was positive or negative.\n","photos":[]},{"id":"2mqr99s8","t":"article","text":"THE GLOBAL VIEW (AACSB)\nWas Nike Responsible for Compensating Honduran Factory Workers?\n\nHonduras is an impoverished country in which 70% of its residents live in poverty. Jobs are scarce, particularly those that pay decent wages along with benefits, such as health care. It is not surprising then that workers at two Honduran factories making products for U.S. companies, including Nike, were extremely upset when their factories closed down and they lost their jobs. Even worse, the owners of the factories refused to pay the 1,800 workers $2 million in severance pay and other benefits due to them by law. Although the factory owners had been paid in full by Nike for the apparel they produced, the workers argued that Nike should be responsible for paying the $2 million in severance that the factory owners had not received.\n\nNike''s original response was to sympathize with the workers but refuse to pay the workers the severance pay they had not received from the factory owners. This stance did not settle well with student groups around the country who rallied in support of the unpaid workers. In the end Nike gave into pressure from the students and paid $1.5 million to a relief fund for the employees. In addition, the company said it would provide vocational training and health coverage for the unemployed workers.\n\nTo learn more about this case, read the following:\n\nNike Press Release: Nike Statement Regarding Vision Tex and Hugger (April 20, 2010)\nhttps://sgbonline.com/nike-to-pay-15mm-to-assist-laid-off-honduran-workers/\nWorking in These Times: Honduran Workers Speak Out Against Nike''s Labor Violations (April 21, 2010)\nhttps://inthesetimes.com/article/honduran-workers-speak-out-against-nikes-labor-violations\nTime Magazine: Just Pay It: Nike Creates Fund for Honduran Workers (July 27, 2010)\nhttps://time.com/archive/6907261/just-pay-it-nike-creates-fund-for-honduran-workers/\nAnswer the following questions:\n\n1.Do you think Nike was responsible for compensating the workers in Honduras? Why did it change its stance?\n\n2.Did the students, universities, and workers themselves have all of the information they needed before becoming involved in the protest? Are their facts accurate?\n\n3.Should students be activists? Do companies such as Nike ignore them at their own peril?","photos":[]}]', 5) ON CONFLICT (id) DO UPDATE SET unit_id = EXCLUDED.unit_id, title = EXCLUDED.title, content = EXCLUDED.content, sort_order = EXCLUDED.sort_order;
INSERT INTO course_sections (id, unit_id, title, content, sort_order) VALUES ('3f394427-1f21-4279-ba2c-18fdd15af64f', 'a6b58d3d-0bd9-48e2-be46-0decc5b9f473', 'Section 1: The Goals of a Business', 'BLOCKS:[{"id":"uig34uq1","t":"desc","text":"Read this article for an overview of basic business concepts. This article will give you a solid foundation for the course material to follow. While the goal of business is to make a profit, there are many other goals. These sections will explain the various types of goals, how they are assessed, the markets they serve, and their impact on society. As you read these pages, make sure to click on any embedded hyperlinks for additional definitions and explanations of the concepts.\n","photos":[]},{"id":"2cxr8eu5","t":"article","text":"The primary purpose of a business is to maximize profits for its owners or stakeholders while maintaining corporate social responsibility.\n\nKey Points\n\nEconomic value added suggests that a principal challenge for a business is balancing the interests of parties affected by the business, interests that are sometimes in conflict with one another.\nAlternate definitions state that a business'' principal purpose is to serve the interests of a larger group of stakeholders, including employees, customers, and even society as a whole.\nMany observers hold that concepts such as economic value added are useful in balancing profit-making objectives with other ends.\nSocial progress is an emerging theme for businesses. It is integral for businesses to maintain high levels of social responsibility.\n\n\nTerms\nstakeholder\nA person or organization with a legitimate interest in a given situation, action, or enterprise.\n\ncorporation\nA group of individuals, created by law or under authority of law, having a continuous existence independent of the existences of its members, and powers and liabilities distinct from those of its members.\n\ncorporate social responsibility (CSR)\nA company''s sense of responsibility towards the community and environment (both ecological and social) in which it operates. Companies express this citizenship (1) through their waste and pollution reduction processes, (2) by contributing educational and social programs and (3) by earning adequate returns on the employed resources.\n\n\n\nExamples\nAmerica has surpassed Europe in revenue growth over time. However, social responsibility may also have a critical role in business operations, so American revenue growth should not be solely considered in corporate success.\nStakeholder theorists believe that people who have legitimate interests in a business should influence its operation. Consumers, and even community members who could be affected by what the business does, ought to have some voice in the decision making.\nAdvocates of business contract theory believe that a business is a community of participants organized around a common purpose. Contract theorists see the enterprise being run by employees and managers as a kind of representative democracy.\n\n\nThe Goals of a Business\nProfit Maximization\nAccording to economist Milton Friedman, the main purpose of a business is to maximize profits for its owners, and in the case of a publicly-traded company, the stockholders are its owners. Others contend that a business''s principal purpose is to serve the interests of a larger group of stakeholders, including employees, customers, and even society as a whole. Philosophers often assert that businesses should abide by some legal and social regulations. Anu Aga, ex-chairperson of Thermax Limited, once said, \"We survive by breathing but we can''t say we live to breathe. Likewise, making money is very important for a business to survive, but money alone cannot be the reason for business to exist\".","photos":[{"path":"lessons/adb82b81-0bbd-4506-921c-36bddd3d8947-Profit_Maximization.png","caption":""}]},{"id":"p4sfg7sv","t":"article","text":"Profit Maximization: This chart depicts profit maximization using the totals approach, where TR = Total Revenue and TC = Total Cost. The profit-maximizing output level is represented as the one at which total revenue is the height of C and total cost is the height of B; the maximal profit is measured as CB.\n\n\n\nSocial Benefit\nMany observers would hold that concepts such as economic value added are useful in balancing profit-making objectives with other ends. They argue that sustainable financial returns are not possible without taking into account the aspirations and interests of other stakeholders such as customers, employees, society and the environment. This concept is called corporate social responsibility (CSR).\n\nThis conception suggests that a principal challenge for a business is to balance the interests of parties affected by the business, interests that are sometimes in conflict with one another. Former President Bill Clinton stated adamantly that major multinational companies must put their customers and employees'' interests before those of shareholders in order to promote economic development and growth, especially in emerging markets. For example, Alibaba, a Chinese Internet venture, strives to operate in the zone that Clinton calls \"double-bottom line capitalism\". The emerging new mantra is to create social progress as well as create profits. In a sense, corporate social responsibility highlights the fact that business, consumers and society are part of a shared ecosystem, and that the long-term health of this ecosystem must be maintained above all else.\n\n\n\nInnovation as a Goal\nRohit Kishore persuades that business can also be viewed to exist for the purpose of creative expansion. Successful firms like Google manage to align their activities towards the purpose of creative expansion from the perspective of all stakeholders, especially employees. This also validates the growing importance of innovation as a core principle for corporation survival and success.\n\n\n\nContract Theory\nAdvocates of business contract theory believe that a business is a community of participants organized around a common purpose. These participants have legitimate interests in how the business is conducted and, therefore, they have legitimate rights over its affairs. Most contract theorists see the enterprise being run by employees and managers as a kind of representative democracy.\n\n\n\nStakeholder Theory\nStakeholder theorists believe that people who have legitimate interests in a business also ought to have voice in how the business is run. However, stakeholder theorists take contract theory a step further, maintaining that people outside of the business enterprise ought to have a say in how the business operates. Thus, for example, consumers, even community members who could be affected by what the business does (for example, by the pollutants of a factory) ought to have some control over the business.\n\n\n\nBusiness as Property\nSome people believe that a business is essentially someone''s property, and, as such, that its owners have the right to dispose of it as they see fit (within the confines of the law and morality). They do not believe that workers or consumers have special rights over the property, other than the right not to be harmed by its use without their consent. In this conception, workers voluntarily exchange their labor for wages from the business owner; they have no more right to tell the owner how he will dispose of his property than the owner has to tell them how to spend their wages. Similarly, assuming the business has purveyed its goods honestly and with full disclosure, consumers have no inherent rights to govern the business, which belongs to someone else.\n\nPeople who subscribe to this view generally point out that a property owner''s rights are constrained by morality. Thus, a homeowner cannot burn down his home and thereby jeopardize the entire neighborhood. Similarly, a business does not have an unlimited right to pollute the air in the manufacturing process.","photos":[]}]', 0) ON CONFLICT (id) DO UPDATE SET unit_id = EXCLUDED.unit_id, title = EXCLUDED.title, content = EXCLUDED.content, sort_order = EXCLUDED.sort_order;
INSERT INTO course_sections (id, unit_id, title, content, sort_order) VALUES ('c7a6359b-abf5-4c34-a257-4404cbb7e77b', 'a6b58d3d-0bd9-48e2-be46-0decc5b9f473', 'When coal plants shut down, what happens next?', 'BLOCKS:[{"id":"z29i9vad","t":"desc","text":"Read this article for an overview of basic business concepts. This article will give you a solid foundation for the course material to follow. While the goal of business is to make a profit, there are many other goals. These sections will explain the various types of goals, how they are assessed, the markets they serve, and their impact on society. As you read these pages, make sure to click on any embedded hyperlinks for additional definitions and explanations of the concepts.\n","photos":[{"path":"lessons/9b26e5b9-1a1e-4e8c-ba50-4fa2ff86fe50-Industrial_Area.jpg","caption":""}]},{"id":"glu19usm","t":"article","text":"An industrial area in the Pilsen neighborhood of Chicago, with the Fisk Generating Station in the background.\n\nAcross the U.S., dozens of coal-fired power plants, many of them decades old, will be going dark in coming years. Now, environmental groups, city planners, elected officials and local residents are turning their attention from the health and environmental impacts of the plants'' emissions to the future of these sites.\n\nUnlike larger, newer coal plants often built in relatively unpopulated areas, many of the old plants slated for retirement are located in or near dense urban areas, including two plants in the heart of Chicago, two in Cleveland and one on the Potomac River near the nation''s capital.\n\nA list of 106 coal plants with anticipated closings announced since 2010, compiled by the Sierra Club, includes 41 Midwestern plants representing more than 4,300 megawatts in Iowa, Ohio, Illinois, Indiana, Wisconsin, Minnesota and Michigan. The list ranges from tiny plants at the University of Wisconsin and a Wisconsin correctional center, to GenOn''s massive Avon Lake station on the shores of Lake Erie near Cleveland.\n\nThe closings mean many people have both hopes and fears about the sites in their midst. Especially for plants on the shores of lakes or rivers or in city neighborhoods lacking green space, there''s much talk of converting the plants to parks or other public spaces. Environmentalists and clean energy boosters have suggested small-scale wind, solar or biomass electricity generation on the sites, to take advantage of existing transmission infrastructure and to make a symbolic statement about converting the old energy economy to the new.","photos":[{"path":"lessons/70071575-be02-4db2-93b3-d56d5494b19c-Industrial_Area.jpg","caption":""}]}]', 4) ON CONFLICT (id) DO UPDATE SET unit_id = EXCLUDED.unit_id, title = EXCLUDED.title, content = EXCLUDED.content, sort_order = EXCLUDED.sort_order;
--> statement-breakpoint
